let allJsonlCount = 0, noneJsonlCount = 0, mixedCount = 0;
const mixedFiles = [];
for (const f of files) {
  const content = fs.readFileSync(path.join(dir, f), "utf8");
  const lines = content.split("\n").filter(l => l.trim().length > 0);
  if (lines.length === 0) { console.log("EMPTY:", f); continue; }
  let okCount = 0;
  for (const line of lines) {
    try { const obj = JSON.parse(line); if (obj && typeof obj === "object") okCount++; } catch (e) {}
  }
  const frac = okCount / lines.length;
  if (frac === 1) allJsonlCount++;
  else if (frac === 0) noneJsonlCount++;
  else { mixedCount++; mixedFiles.push([f, frac, lines.length]); }
}
console.log("all-jsonl:", allJsonlCount, "none-jsonl:", noneJsonlCount, "mixed:", mixedCount);
console.log("mixed files:", mixedFiles);
'

